// P1-S06A: local disposable reference only. Never accepts a hosted database.
import pg from "pg";
import { randomBytes } from "node:crypto";
import { spawnSync } from "node:child_process";
import { databaseSettings } from "../../src/lib/profile";

// Never force-terminate a pool that is still completing its asynchronous close.
// Only names generated by these local control/profile rehearsals are eligible.
export async function dropDisposableLedgerDatabase(
  admin: pg.Client,
  name: string,
) {
  if (
    !/^ledgerone_(controls_[a-f0-9]{16}|profile_[a-f0-9]{12})_test$/.test(name)
  )
    throw new Error("Refusing non-disposable database cleanup");
  const deadline = Date.now() + 5000;
  while (true) {
    const state = await admin.query<{ count: number }>(
      "SELECT count(*)::int AS count FROM pg_stat_activity WHERE datname=$1",
      [name],
    );
    if (state.rows[0]?.count === 0) break;
    if (Date.now() >= deadline)
      throw new Error(
        "Disposable database still has open connections; force deletion refused",
      );
    await new Promise((resolve) => setTimeout(resolve, 25));
  }
  // If another connection races the check, DROP fails safely rather than killing it.
  await admin.query(`DROP DATABASE "${name}"`);
}
export async function createFreshLedgerDatabase(source: string) {
  databaseSettings({ LEDGERONE_ENV: "test", DATABASE_URL: source });
  const input = new URL(source);
  if (
    !["127.0.0.1", "localhost", "[::1]"].includes(input.hostname) ||
    !input.pathname.endsWith("_test") ||
    (input.searchParams.get("schema") &&
      input.searchParams.get("schema") !== "public")
  )
    throw new Error(
      "A loopback public-schema *_test reference source is required",
    );
  const name = `ledgerone_controls_${randomBytes(8).toString("hex")}_test`;
  async function cleanup() {
    const admin = new pg.Client({ connectionString: source });
    try {
      await admin.connect();
      await dropDisposableLedgerDatabase(admin, name);
    } finally {
      await admin.end();
    }
  }
  const admin = new pg.Client({ connectionString: source });
  let created = false;
  try {
    try {
      await admin.connect();
      await admin.query(`CREATE DATABASE "${name}"`);
      created = true;
    } finally {
      await admin.end();
    }
    const target = new URL(input);
    target.pathname = `/${name}`;
    target.searchParams.set("schema", "public");
    const result = spawnSync(
      process.execPath,
      ["node_modules/prisma/build/index.js", "migrate", "deploy"],
      {
        encoding: "utf8",
        env: {
          ...process.env,
          LEDGERONE_ENV: "test",
          DATABASE_URL: target.toString(),
          DIRECT_DATABASE_URL: target.toString(),
          TEST_DATABASE_URL: target.toString(),
        },
      },
    );
    if (result.status !== 0)
      throw new Error(
        "Fresh reference migration failed (output withheld to protect credentials)",
      );
    return { url: target.toString(), cleanup };
  } catch (error) {
    if (created) await cleanup();
    throw error;
  }
}
export async function withFreshLedgerDatabase<T>(
  source: string,
  work: (url: string) => Promise<T>,
) {
  const lease = await createFreshLedgerDatabase(source);
  try {
    return await work(lease.url);
  } finally {
    await lease.cleanup();
  }
}
